// Extract error details from n8n Error Trigger
const item = $input.item.json || {};
const execution = item.execution || {};
const workflow = item.workflow || {};
const error = execution.error || {};

const executionId = String(execution.id || item.executionId || 'unknown');
const workflowName = String(workflow.name || item.workflowName || 'Unknown Workflow');
const workflowId = String(workflow.id || item.workflowId || 'unknown');
const failedNode = String(execution.lastNodeExecuted || error.node?.name || item.node || 'Unknown Node');
const rawMessage = String(error.message || item.message || 'An unexpected automation error occurred.');

// Sanitize error message - redact potential secrets, tokens, emails, medical or sensitive data
let sanitizedMessage = rawMessage
  .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}/g, '[REDACTED_EMAIL]')
  .replace(/(bearer|jwt|token|password|key|secret)\s*[:=]\s*[^\s,;]+/gi, '$1: [REDACTED]')
  .replace(/eyJ[A-Za-z0-9-_=]+\.[A-Za-z0-9-_=]+\.?[A-Za-z0-9-_.+/=]*/g, '[REDACTED_JWT]');

// Truncate message to avoid exceeding message limits or dumping stack traces
if (sanitizedMessage.length > 250) {
  sanitizedMessage = sanitizedMessage.substring(0, 247) + '...';
}

const timestamp = new Date().toISOString();

// Markdown formatted Telegram text (operational metadata only, no request body or medical data)
const formattedText = `🚨 *SchoolPilot Automation Alert*\n• *Workflow*: \`${workflowName}\`\n• *Failing Node*: \`${failedNode}\`\n• *Execution ID*: \`${executionId}\`\n• *Timestamp*: \`${timestamp}\`\n• *Error*: ${sanitizedMessage}`;

return {
  json: {
    alert_type: 'automation_error',
    execution_id: executionId,
    workflow_id: workflowId,
    workflow_name: workflowName,
    failed_node: failedNode,
    sanitized_error: sanitizedMessage,
    timestamp: timestamp,
    formatted_message: formattedText
  }
};
